// edges(follower_id, followee_id, created_at)
// PRIMARY KEY (follower_id, followee_id)
// INDEX on (followee_id, follower_id)  -- for the reverse direction

async function follow(followerId, followeeId) {
  await db.edges.insert({ followerId, followeeId, createdAt: Date.now() });
}

function following(userId) {
  return db.edges.where({ followerId: userId }).select('followeeId');
}

function followers(userId) {
  return db.edges.where({ followeeId: userId }).select('followerId');
}

async function mutualFriends(userA, userB) {
  const [a, b] = await Promise.all([following(userA), following(userB)]);
  const setB = new Set(b);
  return a.filter((id) => setB.has(id));
}

// NAIVE: 1 + N queries, N round trips to the DB
async function friendsOfFriendsNaive(userId) {
  const friends = await following(userId);
  const results = [];
  for (const f of friends) results.push(...(await following(f)));  // N round trips
  return results;
}

async function friendsOfFriends(userId) {
  return db.raw(`
    SELECT DISTINCT e2.followee_id
    FROM edges e1
    JOIN edges e2 ON e2.follower_id = e1.followee_id
    WHERE e1.follower_id = ? AND e2.followee_id != ?
  `, [userId, userId]);
}

function following(userId, { limit = 200, cursor } = {}) {
  return db.edges
    .where({ followerId: userId })
    .andWhere(cursor ? 'followee_id > ?' : '1=1', cursor ? [cursor] : [])
    .orderBy('followee_id')
    .limit(limit);
}
